    ('YELLOW_SPLIT_PEAS', 'Getrocknete gelbe geschälte und halbierte Erbsen; für Suppen, Pürees und Eintöpfe geeignet.'),
    ('YOGURT', 'Durch Milchsäurekulturen gesäuerte Milch mit cremiger bis stichfester Textur; natur und ohne prägende Zusätze gemeint.'),
    ('YUZU', 'Ostasiatische Zitrusfrucht mit intensiv floral-herbem Aroma; meist Saft und Schale, frisch oder ungesüßt konserviert.'),
    ('ZAATAR', 'Levantinische Gewürzmischung typischerweise aus Za’atar-Kraut beziehungsweise Thymian, Sumach, Sesam und Salz; Rezepturen variieren.'),
    ('ZUCCHINI', 'Zucchini als mildes, saftiges Fruchtgemüse; grüne und gelbe sowie längliche und runde Sorten sind umfasst.');
INSERT INTO _ingredient_curator_note_revision (code, curator_note)
VALUES
    ('ALIGUE', 'Philippinische Würzpaste aus ausgelassenem Krabbenfett mit intensiv meeresfruchtig-röstigem Aroma; meist sparsam zum Aromatisieren verwendet.'),
    ('AQUAVIT', 'Mit Kümmel, Dill oder anderen Gewürzen aromatisierte skandinavische Spirituose, die sich auch zum Würzen beim Kochen eignet; nicht auf eine Marke oder ein nationales Rezept beschränkt.'),
    ('BAGOONG_ALAMANG', 'Philippinische salzig-fermentierte Würzpaste aus kleinen Garnelen oder Krill; kräftig umamireich und nicht mit fischbasiertem Bagoong gleichzusetzen.'),
    ('BAGOONG_ISDA', 'Philippinische salzig-fermentierte Würzzutat auf Fischbasis; Fischart und flüssige oder pastöse Konsistenz können regional variieren.'),
    ('BAKED_GOODS', 'Offene Familie gebackener oder vergleichbar ausgebackener stärkehaltiger Produkte; süße und herzhafte Formen sind umfasst.'),
    ('BAMBOO_SHOOTS', 'Junge essbare Bambussprossen mit mildem Geschmack und knackigem Biss; in Deutschland meist vorgegart in Dose oder Glas erhältlich.'),
    ('BAY_LEAF', 'Getrocknetes oder frisches Lorbeerblatt mit herb-würzigem Aroma für Brühen, Saucen und Schmorgerichte; vor dem Servieren üblicherweise entfernen.'),
    ('BRUSSELS_WAFFLE', 'Große rechteckige belgische Waffel nach Brüsseler Art, außen knusprig und innen luftig. Gemeint ist die Waffel selbst, ohne vorausgesetzte Beläge. Nicht mit der kompakteren Lütticher Zuckerwaffel gleichsetzen.'),
    ('CHAMPIGNON', 'Frischer Zuchtchampignon ohne Festlegung auf die weiße oder braune Form; konservierte Champignons und andere Speisepilze sind nicht gemeint.'),
    ('CHILI', 'Frische Chili als Fruchtgemüse; trockene, pulverisierte und eingelegte Formen sind damit nicht gemeint.'),
    ('CHILI_FLAKES', 'Getrocknete Chiliflocken mit variabler Sorte, Schärfe und regionaler Würzung; nicht fein gemahlenes Chilipulver.'),
    ('CHOCOLATE', 'Offene Schokoladenfamilie für dunkle, Milch- und weiße Schokolade; Kakaopulver ist nicht umfasst.'),
    ('COGNAC', 'Geschützter französischer Weinbrand aus Cognac mit charakteristisch gereiftem Aroma; nicht beliebiger Brandy oder Weinbrand.'),
    ('COCONUT_PRODUCTS', 'Offene Familie für Kokosfrucht, Kokoswasser, daraus gewonnene Emulsionen, Fett und weitere verarbeitete Kokosprodukte.'),
    ('CONFECTIONERY', 'Offene Familie verzehrfertiger Süßwaren wie Bonbons, Lakritz oder Marzipan; reine Süßungsmittel und Backgrundstoffe sind nicht automatisch umfasst.'),
    ('DAIRY_PRODUCTS', 'Offene Familie von Milchprodukten wie Milch, Rahm, fermentierten Erzeugnissen, Butter und Käse; Eier und pflanzliche Alternativen sind nicht gemeint.'),
    ('DRIED_CHILI', 'Ganze oder grob zerteilte getrocknete Chili mit konzentriertem Aroma; Pulver und feine Flocken sind damit nicht gemeint.'),
    ('FROG_LEGS', 'Essbare Froschschenkel mit zartem, mildem Fleisch; frisch oder tiefgekühlt als ganze Schenkelpaare beziehungsweise Teilstücke verwendbar.'),
    ('GARLIC_POWDER', 'Getrockneter gemahlener oder granulierter Knoblauch mit konzentriertem Aroma; nicht frischer Knoblauch oder Knoblauchsalz.'),
    ('GOCHUJANG', 'Koreanische fermentierte rote Chilipaste mit dicklicher Konsistenz sowie süß-scharfem, salzigem und umamireichem Profil.'),
    ('GREEN_SPLIT_PEAS', 'Getrocknete grüne geschälte und halbierte Erbsen mit mild-erdigem Geschmack; nicht gelbe Schälerbsen oder frische grüne Erbsen.'),
    ('HAM', 'Offene Schinkenfamilie aus gepökeltem Fleisch; gekochte, geräucherte und luftgetrocknete Ausprägungen sind umfasst.'),
    ('LAMBIC', 'Traditioneller belgischer Bierstil aus spontan vergorener Würze. Gemeint ist der Grundstil; Gueuze, Kriek und andere Frucht- oder Blendvarianten sind nicht automatisch eingeschlossen.'),
    ('LINGONBERRY_PRESERVES', 'Gesüßte Preiselbeerzubereitung wie Konfitüre, Kompott oder gerührte Preiselbeeren; nicht die ungesüßte frische Beere.'),
    ('LIQUORICE', 'Lakritzware mit süßen und salzigen Ausprägungen, auch als Kochzutat verwendbar; nicht Süßholzwurzel oder reiner Lakritzextrakt.'),
    ('LOBSTER', 'Hummer mit festem, süßlichem Fleisch aus Schwanz und Scheren; ganz, ausgelöst, frisch oder tiefgekühlt verwendbar.'),
    ('MAGGI_SEASONING', 'Dunkle flüssige Würzsauce nach Maggi-Art mit salzig-würzigem Umami; nicht Liebstöckel, Sojasauce oder Brühwürfel.'),
    ('MISO', 'Japanische fermentierte Würzpaste auf Sojabohnenbasis, häufig mit Reis oder Gerste; Farbe, Salzgehalt und Reifegrad bleiben offen.'),
    ('MYCOPROTEIN', 'Pilzproteinbasierte Fleischalternative; Marke, Produktform und Würzung können variieren.'),
    ('NORWEGIAN_WAFFLE', 'Dünne, weiche Waffel nach norwegischer Art, typischerweise herzförmig, leicht süß und mit Kardamom aromatisiert. Gemeint ist die Waffel selbst, ohne vorausgesetzte Beläge.'),
    ('OKRA', 'Junge Okraschoten mit grasig-mildem Geschmack; ihre Samen und Schleimstoffe entwickeln beim Garen eine charakteristische Bindung.'),
    ('ONION_POWDER', 'Getrocknete gemahlene oder granulierte Zwiebel mit konzentriertem Aroma; nicht frische Zwiebel oder Zwiebelsalz.'),
    ('PAPRIKA_POWDER', 'Paprikapulver als Gewürzfamilie mit süßen, scharfen und geräucherten Varianten; nicht frische Paprika.'),
    ('PICKLED_CHILI', 'In Essig- oder Gewürzlake eingelegte ganze oder geschnittene Chili; Sorte und Schärfe bleiben offen, trockene Formen sind nicht gemeint.'),
    ('PICKLED_MUSHROOMS', 'In Essiglake eingelegte Speisepilze; eine Fermentation wird nicht vorausgesetzt.'),
    ('PIMENT_D_ESPELETTE', 'Getrocknetes, fein gemahlenes Piment-d’Espelette-Gewürz nach französisch-baskischer Art; nicht generisches Chilipulver oder die frische ganze Schote.'),
    ('PLANT_DRINKS', 'Offene Familie flüssiger pflanzlicher Milchalternativen etwa aus Soja, Hafer oder Nüssen; Rohstoff und Süßung bleiben wählbar.'),
    ('READY_CURRY_PASTE', 'Offene Familie verzehrfertiger Currypasten mit bereits kombinierter Gewürz- und Aromatenbasis; Küche, Farbe und Schärfe bleiben offen.'),
    ('READY_SAUCES_AND_PASTES', 'Offene Familie gebrauchsfertiger Saucen, Würzen und Pasten mit bereits zusammengesetztem Geschmacksprofil.'),
    ('ROOKWORST', 'Niederländische geräucherte Koch- oder Brühwurst; die Fleischzusammensetzung kann variieren und muss nicht ausschließlich aus Schweinefleisch bestehen.'),
    ('SAFFRON', 'Getrocknete Safranfäden beziehungsweise Narben mit intensiv floral-honigartigem Aroma und starker gelber Färbekraft; sparsam dosieren.'),
    ('SAMBAL', 'Chilipaste oder Chilisauce mit je nach Variante unterschiedlicher Schärfe, Konsistenz und Aromatik; nicht auf Sambal Oelek beschränkt.'),
    ('SEITAN', 'Festes proteinreiches Lebensmittel aus ausgewaschenem oder isoliertem Weizengluten; natur oder neutral vorgewürzt verwendbar.'),
    ('SOBA', 'Japanische dünne Nudeln mit Buchweizen als typischem Teigbestandteil; Buchweizenanteil und Beimischung von Weizen können variieren.'),
    ('STROOPWAFEL', 'Zwei dünne Waffeln mit süßer Sirup- oder Karamellfüllung; gemeint ist die fertige Süßware, nicht eine allgemeine Waffel oder der Sirup allein.'),
    ('TEMPEH', 'Fester fermentierter Kuchen aus ganzen Sojabohnen mit nussigem Aroma und gutem Biss; nicht Tofu oder texturiertes Sojaprotein.'),
    ('TRUFFLE', 'Essbare Trüffel mit intensiv erdigem Aroma; frisch oder als hochwertiges Produkt mit erkennbarem Trüffelanteil verwendbar.'),
    ('TWAROG', 'Polnischer frischer Sauermilch- oder Bruchkäse mit krümeligem bis cremigem Gefüge; Quark ist als Ersatz ähnlich, aber nicht identisch. Nicht mit körnigem Hüttenkäse gleichsetzen.'),
    ('UBE', 'Violette Yamswurzel mit mild-süßlichem, nussigem Aroma; frisch, tiefgekühlt oder als ungesüßtes Püree, nicht violette Süßkartoffel.'),
    ('WAFFLES', 'Offene Waffelfamilie für süße und herzhafte Waffelprodukte. Bekannte Varianten sind Stroopwafel, Brüsseler Waffel und Lütticher Waffel; Belag oder Füllung werden nicht vorausgesetzt.');
