--liquibase formatted sql

--changeset venomenon328:028-curator-note-completeness splitStatements:false
-- Issue #178: backfill concise editorial notes for every ingredient concept that
-- still lacks one, then make the completeness invariant permanent.

CREATE TEMP TABLE _ingredient_curator_note_backfill (
    code text PRIMARY KEY,
    curator_note text NOT NULL CHECK (btrim(curator_note) <> '')
) ON COMMIT DROP;





CREATE TEMP TABLE _ingredient_curator_note_revision (
    code text PRIMARY KEY,
    curator_note text NOT NULL CHECK (btrim(curator_note) <> '')
) ON COMMIT DROP;


DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM _ingredient_curator_note_backfill source
        LEFT JOIN ingredient_concept concept ON concept.code = source.code
        WHERE concept.id IS NULL
    ) THEN
        RAISE EXCEPTION 'Curator-note backfill contains an unknown ingredient concept code';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM ingredient_concept concept
        WHERE (concept.curator_note IS NULL OR btrim(concept.curator_note) = '')
          AND NOT EXISTS (
              SELECT 1
              FROM _ingredient_curator_note_backfill source
              WHERE source.code = concept.code
          )
    ) THEN
        RAISE EXCEPTION 'Ingredient catalog contains an unreviewed concept without a curator note';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM _ingredient_curator_note_revision source
        LEFT JOIN ingredient_concept concept ON concept.code = source.code
        WHERE concept.id IS NULL
    ) THEN
        RAISE EXCEPTION 'Curator-note revision contains an unknown ingredient concept code';
    END IF;
END;
$$;

UPDATE ingredient_concept concept
SET curator_note = source.curator_note
FROM _ingredient_curator_note_backfill source
WHERE concept.code = source.code
  AND (concept.curator_note IS NULL OR btrim(concept.curator_note) = '');

UPDATE ingredient_concept concept
SET curator_note = source.curator_note
FROM _ingredient_curator_note_revision source
WHERE concept.code = source.code;

DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM ingredient_concept
        WHERE curator_note IS NULL OR btrim(curator_note) = ''
    ) THEN
        RAISE EXCEPTION 'Ingredient catalog still contains a blank curator note after backfill';
    END IF;
END;
$$;

ALTER TABLE ingredient_concept
    ALTER COLUMN curator_note SET NOT NULL;

ALTER TABLE ingredient_concept
    ADD CONSTRAINT ck_ingredient_concept_curator_note_not_blank
        CHECK (btrim(curator_note) <> '');
